.stories DW netiquette policy: https://p.dw.com/p/MF1G","thumbnail":"https://i.ytimg.com/vi/KqM9O6vs9nY/maxresdefault.jpg","category":"Documentaries","city":"","country":"","channel":"DW Documentary","channelTitle":"DW Documentary","channelId":"UCW39zufHfsuGgpLviKh297Q","badge":"DOCUMENTARY","publishedAt":"2020-11-15T17:00:08Z","viewCount":36810,"durationSeconds":2485,"admission":{"version":3,"status":"channel-candidate","source":"channel-archive","mode":"DOCUMENTARIES"}}',1);
